head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/

scwin.vScrenID = "ULDFIS00400_01.xml";
// 전역 변수 선언
scwin.vKisCd = "";

/**
 *  화면이 최초 로드될때 실행되는 초기화 이벤트
 *  (초기 데이터 조회나 컴포넌트 설정) 
 */

// scwin.onpageload, scwin.onpageunload 함수
scwin.onpageload = function() {
    scwin.init();
};

/**
 *  현재 로딩된 페이지가 초기화되거나 종료될때(다른 화면으로 이동하거나 페이지를 닫기전) 발생하는 이벤트
 *  (주로 SPA(Single Page Application) 환경에서 전역 자원을 해제하거나 메모리 누수 방지)
 */
scwin.onpageunload = function() {

};

// WebSquare 컴포넌트 이벤트 함수
/**
 *  감사의견 그리드 더블클릭 후 감사의견 팝업 호출
 */
scwin.grd_AudtOpinSpeclablContn_oncelldblclick = function (rowIndex, columnIndex, columnId) {

    if (columnId === "audtOpinNm") {

        if(dlt_consNotesAudOpnListRes.getCellData(rowIndex, "ctnt") === 1) {

            scwin.audtOpinSrchOpen(rowIndex);

        }

    }

};

// 일반 함수
/**
 *  화면 초기화
 */
scwin.init = function() {
    scwin.search();
};

/**
 *  데이터셋 초기화.
 */
scwin.initDs = function() {
    dlt_consNotesAudOpnListRes.setData([]);    
};

/**
 *  조회조건 유효성 체크
 */
scwin.chkValid = function() {

    vKisCd = $p.parent().frame_head.getWindow().scwin.fn_GetKisCd();

    if (vKisCd === "") {
        return false;    
    }

    return true;
};

/**
 * 감사의견 조회
 */
scwin.search = async function() {
    //데이터셋 초기화
    scwin.initDs();

    // 조회조건 체크
    if (!scwin.chkValid()) {
        return;
    }

    dma_consNotesAudOpnInfoReq.set("kisCd", vKisCd);
    const sbmOptions = {
        id : "sbm_consNotesAudOpn",
        action : "/api/listing/nice/financial/cons-notes/aud-opn",
        method : "get",
        ref : "dma_consNotesAudOpnInfoReq",
        target : "dlt_consNotesAudOpnListRes|append",
        gridview : "grd_AudtOpinSpeclablContn",
        isProcessMsg : false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    dlt_consNotesAudOpnListRes.setJSON(res.responseJSON.body);

};

/**
 * 감사의견 팝업
 */
scwin.audtOpinSrchOpen = async function(pRow) {

    const url = "/ui/lst/fis/ULDFIS00300_P1.xml";
    const popTitle = "감사의견 검색";
    const opts = {
        id: "ULDFIS00300_P1",
        popupName: popTitle,
        width: 700,
        height: 590,
        frameModal: "top",
    };

    // 적정인경우 스킵
    if (dlt_consNotesAudOpnListRes.getCellData(pRow, "audtOpinCd") === "10") {
        // return;
    }

    const popData = dlt_consNotesAudOpnListRes.getRowJSON(pRow);
    const res = await $c.win.openPopup(url, opts, popData);

};

/**
 *  엑셀파일다운로드
 */
scwin.excelDownload = function() {

    if (dlt_consNotesAudOpnListRes.getRowCount() <= 0) {
        alert("조회된 데이터가 없습니다.");
        return;
    }

    const options = {
        fileName : "감사의견" 
    };

    const infoArray = {};

    $c.data.downloadGridViewExcel(grd_AudtOpinSpeclablContn, options, infoArray);

};
